"use strict";(self.webpackChunkspotify_docs=self.webpackChunkspotify_docs||[]).push([[8043],{54376:t=>{t.exports=JSON.parse('{"tag":{"label":"test","permalink":"/spotify-docs/docs/tags/test","allTagsPath":"/spotify-docs/docs/tags","count":16,"items":[{"id":"Documentation/Access_Token","title":"Access Token","description":"An access token is a string that holds your credentials and permissions, allowing you to access Spotify resources (e.g., artists, albums, tracks) or user data (e.g., your profile or playlists).","permalink":"/spotify-docs/docs/Documentation/Access_Token"},{"id":"Documentation/API_Calls","title":"API Calls","description":"The Spotify Web API is a RESTful API that provides JSON metadata about music artists, albums, and tracks directly from the Spotify Data Catalogue.","permalink":"/spotify-docs/docs/Documentation/API_Calls"},{"id":"Documentation/Apps","title":"Apps","description":"The app provides, among others, the Client ID and Client Secret needed to implement any of the authorization flows.","permalink":"/spotify-docs/docs/Documentation/Apps"},{"id":"Documentation/Authorization_code","title":"Authorization Code","description":"The Authorization Code Flow is ideal for long-running applications, such as web and mobile apps, where users grant permission once and it persists.","permalink":"/spotify-docs/docs/Documentation/Authorization_code"},{"id":"tutorial-basics/congratulations","title":"Congratulations!","description":"You have just learned the basics of Docusaurus and made some changes to the initial template.","permalink":"/spotify-docs/docs/tutorial-basics/congratulations"},{"id":"tutorial-basics/create-a-blog-post","title":"Create a Blog Post","description":"Docusaurus creates a page for each blog post, but also a blog index page, a tag system, an RSS feed...","permalink":"/spotify-docs/docs/tutorial-basics/create-a-blog-post"},{"id":"tutorial-basics/create-a-page","title":"Create a Page","description":"Add Markdown or React files to src/pages to create a standalone page:","permalink":"/spotify-docs/docs/tutorial-basics/create-a-page"},{"id":"Documentation/Getting_Started","title":"Getting Started","description":"This guide will walk you through making your first Spotify Web API call to retrieve an artist\'s metadata. Follow these simple steps to get started and unleash your creativity!","permalink":"/spotify-docs/docs/Documentation/Getting_Started"},{"id":"tutorial-extras/manage-docs-versions","title":"Manage Docs Versions","description":"Docusaurus can manage multiple versions of your docs.","permalink":"/spotify-docs/docs/tutorial-extras/manage-docs-versions"},{"id":"Documentation/overview","title":"Overview","description":"Welcome to the Spotify Web API documentation! This is where the magic begins. Follow the steps below to embark on your journey to create awesome music applications using the Spotify Web API.","permalink":"/spotify-docs/docs/Documentation/overview"},{"id":"Documentation/Rate_Limits","title":"Rate Limits","description":"If your app makes a high volume of Web API requests in a short period, it may receive a 429 Too Many Requests error response from Spotify. This indicates that your app has exceeded the Web API rate limit, which is designed to ensure API reliability and encourage responsible usage by third-party developers.","permalink":"/spotify-docs/docs/Documentation/Rate_Limits"},{"id":"Documentation/Redirect_URIs","title":"Redirect URIs","description":"Beginning on the 9th of April 2025 we will enforce the subsequent validations to all newly created apps.","permalink":"/spotify-docs/docs/Documentation/Redirect_URIs"},{"id":"Documentation/Refresh_Token","title":"Refresh Token","description":"A refresh token is a security credential that allows client applications to obtain new access tokens without requiring users to reauthorize the application.","permalink":"/spotify-docs/docs/Documentation/Refresh_Token"},{"id":"Documentation/Spotify_URIs_and_IDs","title":"Spotify URIs and IDs","description":"When interacting with the Spotify Web API, you\u2019ll frequently encounter various identifier parameters in requests and responses. Below are the key types of identifiers and how to use them.","permalink":"/spotify-docs/docs/Documentation/Spotify_URIs_and_IDs"},{"id":"tutorial-extras/translate-your-site","title":"Translate your site","description":"Let\'s translate docs/intro.md to French.","permalink":"/spotify-docs/docs/tutorial-extras/translate-your-site"},{"id":"intro","title":"Tutorial Intro","description":"Let\'s discover Docusaurus in less than 5 minutes.","permalink":"/spotify-docs/docs/intro"}],"unlisted":false}}')}}]);